const L = raquetAlgebraLib;
const BLOCK_FUNCTION = 'RAQUET_DB.RAQUET.__RASTER_ALGEBRA_BLOCK';

if (!Array.isArray(INPUTS) || INPUTS.length === 0) {
    throw new Error('RASTER_ALGEBRA: at least one input raster is required');
}
if (OUTPUT_TABLE === null || OUTPUT_TABLE === undefined) {
    throw new Error('RASTER_ALGEBRA: OUTPUT_TABLE cannot be NULL');
}

// Read each input's metadata row and actual column names
// (names validated before interpolation; user quoting is preserved)
const inputColumns = [];
const metadatas = INPUTS.map((t, i) => {
    const name = L.snowflakeTableName(t, 'input ' + L.inputRef(i));
    // Column names are only available on a Statement (not on a ResultSet)
    const stmt = snowflake.createStatement({ sqlText: `SELECT * FROM ${name} LIMIT 0` });
    try {
        stmt.execute();
    } catch (e) {
        throw new Error(`RASTER_ALGEBRA: input ${name} could not be read: ${e.message}`);
    }
    const columns = [];
    for (let c = 1; c <= stmt.getColumnCount(); c++) columns.push(stmt.getColumnName(c));
    inputColumns.push(columns);
    const metadataColumn = columns.find(c => c.toLowerCase() === 'metadata');
    const blockColumn = columns.find(c => c.toLowerCase() === 'block');
    if (!metadataColumn || !blockColumn) {
        throw new Error(`RASTER_ALGEBRA: input ${name} is not a RaQuet raster (no block/metadata columns)`);
    }
    const q = c => '"' + c.replace(/"/g, '""') + '"';
    const md = snowflake.execute({
        sqlText: `SELECT ${q(metadataColumn)} FROM ${name} WHERE ${q(blockColumn)} = 0 AND ${q(metadataColumn)} IS NOT NULL LIMIT 1`
    });
    return md.next() ? md.getColumnValue(1) : null;
});

// Validate everything before creating anything (no output on failure)
const plan = L.plan(EXPRESSION, metadatas, OPTIONS);
const output = L.snowflakeTableName(OUTPUT_TABLE, 'output');

// Fails if the output table already exists
snowflake.execute({ sqlText: L.buildSnowflakeSql(plan, INPUTS, OUTPUT_TABLE, BLOCK_FUNCTION, inputColumns) });

let numBlocks;
try {
    const statsRs = snowflake.execute({ sqlText: L.buildSnowflakeStatsSql(plan, OUTPUT_TABLE) });
    statsRs.next();
    const stats = statsRs.getColumnValue(1);
    numBlocks = JSON.parse(stats).num_blocks;
    const metadata = L.buildMetadata(plan, stats, {
        inputs: INPUTS.map(t => String(t).trim()),
        created_by: 'raquet RASTER_ALGEBRA (Snowflake)'
    });
    snowflake.execute({ sqlText: L.buildSnowflakeMetadataInsertSql(OUTPUT_TABLE), binds: [metadata] });
} catch (e) {
    snowflake.execute({ sqlText: `DROP TABLE IF EXISTS ${output}` });
    throw e;
}

return JSON.stringify({ output_table: output, num_blocks: numBlocks });
